function best(id){return store.get('bt_best_'+id,0)} function saveBest(id,n){if(n>best(id))store.set('bt_best_'+id,n)}
function renderCards(filter='all'){grid.innerHTML='';games.filter(g=>filter==='all'||g.age.includes(filter)||g.age===filter||(filter==='3-5'&&g.age==='3-8')||(filter==='6-8'&&['3-8','6-10'].includes(g.age))||(filter==='9-10'&&['6-10','9-10','3-10'].includes(g.age))).forEach(g=>{const c=document.createElement('article');c.className='gameCard';c.style.setProperty('--cardGlow',g.glow);c.innerHTML=`${g.new?'<span class="newTag">NUOVO</span>':''}<div class="gameIcon">${g.icon}</div><span class="ageTag">${g.age.replace('-', '–')} ANNI</span><h3>${g.name}</h3><p>${g.desc}</p><button class="playBtn">▶ Gioca</button>`;$('.playBtn',c).addEventListener('click',()=>openGame(g));grid.append(c)})}
renderCards();
